import{_ as t,o as s,c as o,k as e,a}from"./chunks/framework.FHZ5yb6k.js";const k=JSON.parse('{"title":"杂谈","description":"","frontmatter":{"title":"杂谈","author":"Ray","date":"2025/10/01 10:24","categories":["生活"],"tags":["其他"]},"headers":[],"relativePath":"notes/life/杂谈.md","filePath":"notes/life/杂谈.md","lastUpdated":1784696549000}'),n={name:"notes/life/杂谈.md"},i=e("h2",{id:"关于ai",tabindex:"-1"},[a("关于AI "),e("a",{class:"header-anchor",href:"#关于ai","aria-label":'Permalink to "关于AI"'},"​")],-1),r=e("p",null,"不得不感叹ai的发展之迅速，短短数年之内，已经从实验室走向了企业落地，其带来的人与生产工具的关系的变革也是前所未有的，甚至于人的劳动地位也被逐渐代替。从2026年这个节点来看，AI是弊略大于利，因为技术没有实现完全替代人力，但是AI极大地吞噬了本属于人的工作岗位，中美目前都是如此，程序员目前已经没有所谓的金三银四了，薪资待遇也大幅度地降低，所有企业都希望通过搭建agent来取代人力成本，程序员群体目前遭受严酷的寒冬。我从小红书和短视频平台通过搜索发现确实没有了以往炫耀薪资的那种帖子，大家都趋向于保守策略来应对可能的裁员失业等情况。",-1),c=e("h3",{id:"身为程序员能做什么",tabindex:"-1"},[a("身为程序员能做什么 "),e("a",{class:"header-anchor",href:"#身为程序员能做什么","aria-label":'Permalink to "身为程序员能做什么"'},"​")],-1),d=e("p",null,"积极地拥抱AI，我们不是规则的制定者，但是我们却可以利用规则。现在打开Boss直聘等求职软件，发现ai-agent的岗位要比原来更多，但是所有企业都希望能招到的是已经成熟落地的，能跑通agent在企业中真正发挥作用的优秀人才，哪有那么多匹配合适的呢？我的看法是可以适当地进行包装，如果不包装的话，你在竞争中就处于巨大劣势。",-1),l=[i,r,c,d];function _(h,p,f,m,u,g){return s(),o("div",null,l)}const A=t(n,[["render",_]]);export{k as __pageData,A as default};
